                        (value || '').replace(/\s+/g, ' ').trim();

                      const range1Str = charsRangesArrays[1]
                        ?.map(g => g?.unicode || '')
                        .join('');

                      const range2Str = charsRangesArrays[2]
                        ?.map(g => g?.unicode || '')
                        .join('');

                      const recoverRange2 =
                        useRelatedRange &&
                        !!range2Str &&
                        normalizeText(`${range1Str}${range2Str}`) ===
                        normalizeText(cur.str) &&
                        normalizeText(cur.str) ===
                        normalizeText(relatedTextContentItem.str);

