                      // (
                      //     tableContentItems?.[currentCoordinate.eolIndex]?.['paddingTop'] ?
                      //         (lastItem.transform[5] - lastItem.height - newItem?.transform?.[5]) == tableContentItems[currentCoordinate.eolIndex]['paddingTop']
                      //         : true
